use verus::prelude::*;

verus! {

/// Given a non-empty slice of i32, returns its maximum element by
/// scanning the array in reverse order.
///
/// Requirements:
///   - `arr.len() > 0`
///
/// Guarantees:
///   - The returned `max` is at least as large as every element of `arr`.
///   - There exists at least one index `j` such that `arr[j] == max`.
pub fn maxArrayReverse(arr: &[i32]) -> (max: i32)
    requires
        arr.len() > 0,
    ensures
        // Every element is ≤ max
        forall(|j: usize| j < arr.len() ==> arr[j] <= max),
    ensures
        // There is at least one element equal to max
        exists(|j: usize| j < arr.len() && arr[j] == max),
{
    // We will maintain a loop index `i` that marks the lower bound of
    // the "processed" suffix of the array: indices `i .. arr.len()`.
    // We also maintain `max_val` as the maximum over that suffix.
    let mut i: usize = arr.len() - 1;
    let mut max_val: i32 = arr[i];
    while i > 0
        invariant
            // 0 <= i < arr.len()
            0 <= i && i < arr.len(),
        invariant
            // All processed elements ≤ max_val
            forall(|k: usize| i <= k && k < arr.len() ==> arr[k] <= max_val),
        invariant
            // There is at least one processed element equal to max_val
            exists(|k: usize| i <= k && k < arr.len() && arr[k] == max_val),
        decreases
            i,
    {
        // Examine the next element just before index i
        let x = arr[i - 1];
        if x > max_val {
            max_val = x;
        }
        // Shrink the processed suffix to include index i-1
        i = i - 1;
    }

    // At this point, i == 0, so the processed suffix is 0 .. arr.len(),
    // i.e., the entire array. The invariants ensure the postconditions.
    max_val
}

}